contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 rStateParam) public payable {
        // Snapshot values needed to express the rule over every input.
        // These read-only getters must exist in C's public surface (they do inherit GSPStorage/GSPVault).
        uint256 beforeRState = c._RState_();
        uint256 beforeBaseReserve = uint256(c._BASE_RESERVE_());
        uint256 beforeQuoteReserve = uint256(c._QUOTE_RESERVE_());
        uint256 beforeBaseTarget = uint256(c._BASE_TARGET_());
        uint256 beforeQuoteTarget = uint256(c._QUOTE_TARGET_());

        // Drive the deciding call: a top-level state-changing call.
        c.correctRState();

        uint256 afterRState = c._RState_();
        uint256 afterBaseTarget = uint256(c._BASE_TARGET_());
        uint256 afterQuoteTarget = uint256(c._QUOTE_TARGET_());

        // General rule:
        // - The BELOW_ONE branch executes iff RState == BELOW_ONE and baseReserve < baseTarget.
        //   In that case RState becomes ONE and both targets equal their reserves.
        // - The ABOVE_ONE branch executes iff RState == ABOVE_ONE and quoteReserve < quoteTarget.
        //   In that case RState becomes ONE and both targets equal their reserves.
        // - Otherwise _QUOTE_TARGET_ remains unchanged.
        bool belowBranch = (beforeRState == uint256(1) && beforeBaseReserve < beforeBaseTarget);
        bool aboveBranch = (beforeRState == uint256(2) && beforeQuoteReserve < beforeQuoteTarget);

        if (belowBranch || aboveBranch) {
            assert(afterRState == uint256(0));
            assert(afterBaseTarget == beforeBaseReserve);
            assert(afterQuoteTarget == beforeQuoteReserve);
        } else {
            assert(afterQuoteTarget == beforeQuoteTarget);
        }
    }

    receive() external payable {}
}

