                ? (rStateAfter == 0 && baseReserveAfter == baseReserveBefore && quoteReserveAfter == quoteReserveBefore && baseTargetAfter == baseReserveBefore && quoteTargetAfter == quoteReserveBefore)
                : (rStateAfter == rStateBefore && baseReserveAfter == baseReserveBefore && quoteReserveAfter == quoteReserveBefore && baseTargetAfter == baseTargetBefore && quoteTargetAfter == quoteTargetBefore)
